From ef6d7cccd3d290ff4feb1865ff0fc65a2f015ba1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:35:03 +0100
Subject: [PATCH] shell/osd: list all keyboard layouts when switching layout

The keyboard layout OSD only showed the name of the new layout, so it
didn't tell how many layouts there are or which one the next switch will
pick. It now lists every layout and highlights the one that became active.

BUG: 506001
---
 shell/osd.cpp         | 48 +++++++++++++++++++++++++++++++++++++++++--
 shell/osd.h           |  1 +
 shell/qml/Osd.qml     |  2 ++
 shell/qml/OsdItem.qml | 42 ++++++++++++++++++++++++++++++++++++-
 4 files changed, 90 insertions(+), 3 deletions(-)

diff --git a/shell/osd.cpp b/shell/osd.cpp
index 53c8b03f59..01aadf60c9 100644
--- a/shell/osd.cpp
+++ b/shell/osd.cpp
@@ -12,6 +12,8 @@

 #include <QDBusConnection>
 #include <QDBusMessage>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
 #include <QDBusReply>
 #include <QDebug>
 #include <QQmlComponent>
@@ -142,9 +144,44 @@ void Osd::mediaPlayerVolumeChanged(int percent, const QString &playerName, const

 void Osd::kbdLayoutChanged(const QString &layoutName)
 {
-    if (m_osdConfigGroup.readEntry("kbdLayoutChangedEnabled", true)) {
-        showText(u"keyboard-layout"_s, layoutName);
+    if (!m_osdConfigGroup.readEntry("kbdLayoutChangedEnabled", true)) {
+        return;
     }
+
+    // Show all layouts and the position of the new one, so it's clear where the next switch leads
+    const QDBusMessage layoutCall = QDBusMessage::createMethodCall(u"org.kde.keyboard"_s, u"/Layouts"_s, u"org.kde.KeyboardLayouts"_s, u"getLayout"_s);
+    const QDBusPendingReply<uint> layoutReply = QDBusConnection::sessionBus().asyncCall(layoutCall);
+    const QDBusMessage listCall = QDBusMessage::createMethodCall(u"org.kde.keyboard"_s, u"/Layouts"_s, u"org.kde.KeyboardLayouts"_s, u"getLayoutsList"_s);
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(listCall), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, layoutName, layoutReply](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+
+        QDBusPendingReply<uint> currentLayout = layoutReply;
+        currentLayout.waitForFinished();
+
+        QStringList layouts;
+        const QDBusMessage reply = watcher->reply();
+        if (!watcher->isError() && !currentLayout.isError() && reply.arguments().size() == 1) {
+            const auto argument = reply.arguments().constFirst().value<QDBusArgument>();
+            argument.beginArray();
+            while (!argument.atEnd()) {
+                QString shortName;
+                QString displayName;
+                QString longName;
+                argument.beginStructure();
+                argument >> shortName >> displayName >> longName;
+                argument.endStructure();
+                layouts.append(longName);
+            }
+            argument.endArray();
+        }
+
+        if (layouts.size() > 1 && currentLayout.value() < uint(layouts.size())) {
+            showList(u"keyboard-layout"_s, layoutName, layouts, currentLayout.value());
+        } else {
+            showText(u"keyboard-layout"_s, layoutName);
+        }
+    });
 }

 void Osd::virtualDesktopChanged(const QString &currentVirtualDesktopName)
@@ -290,6 +327,11 @@ void Osd::showProgress(const QString &icon, const int percent, const int maximum
 }

 void Osd::showText(const QString &icon, const QString &text)
+{
+    showList(icon, text, {}, -1);
+}
+
+void Osd::showList(const QString &icon, const QString &text, const QStringList &items, int currentIndex)
 {
     if (!init()) {
         return;
@@ -297,6 +339,8 @@ void Osd::showText(const QString &icon, const QString &text)

     m_osdObject->setProperty("showingProgress", false);
     m_osdObject->setProperty("osdValue", text);
+    m_osdObject->setProperty("osdList", items);
+    m_osdObject->setProperty("osdListIndex", currentIndex);
     m_osdObject->setProperty("icon", icon);

     Q_EMIT osdText(icon, text);
diff --git a/shell/osd.h b/shell/osd.h
index bc1071db58..c6ec538811 100644
--- a/shell/osd.h
+++ b/shell/osd.h
@@ -54,6 +54,7 @@ private:
     bool init();

     void showProgress(const QString &icon, const int percent, const int maximumPercent, const QString &additionalText = QString(), bool showOnMobile = true);
+    void showList(const QString &icon, const QString &text, const QStringList &items, int currentIndex);
     void showOsd();

     ShellCorona *const m_corona;
diff --git a/shell/qml/Osd.qml b/shell/qml/Osd.qml
index bb8703e09a..d1b2c65d6a 100644
--- a/shell/qml/Osd.qml
+++ b/shell/qml/Osd.qml
@@ -21,6 +21,8 @@ OsdWindow {
     property alias osdAdditionalText: osd.osdAdditionalText
     property alias icon: osd.icon
     property alias showingProgress: osd.showingProgress
+    property alias osdList: osd.osdList
+    property alias osdListIndex: osd.osdListIndex

     width: Math.max(Math.min(Screen.desktopAvailableWidth / 2, mainItem.implicitWidth), Kirigami.Units.gridUnit * 15) +  leftPadding + rightPadding
     height: mainItem.implicitHeight + topPadding + bottomPadding
diff --git a/shell/qml/OsdItem.qml b/shell/qml/OsdItem.qml
index 43b80e3b96..c4aa8c18c4 100644
--- a/shell/qml/OsdItem.qml
+++ b/shell/qml/OsdItem.qml
@@ -29,6 +29,10 @@ RowLayout {
     // Set to true if the value is meant for progress bar,
     // false for displaying the value as normal text
     property bool showingProgress: false
+    // Items to list instead of the text, e.g. all keyboard layouts,
+    // with the one at osdListIndex highlighted
+    property var osdList: []
+    property int osdListIndex: -1

     function formatPercent(number) {
         return i18nc("Percentage value", "%1%", number);
@@ -67,7 +71,43 @@ RowLayout {
             wrapMode: Text.NoWrap
             elide: Text.ElideRight
             text: (root.showingProgress ? root.osdAdditionalText : root.osdValue) ?? ""
-            visible: text != ""
+            visible: text != "" && !list.visible
+        }
+
+        ColumnLayout {
+            id: list
+            Layout.fillWidth: true
+            Layout.leftMargin: iconItem.valid ? 0 : Kirigami.Units.smallSpacing
+            Layout.rightMargin: Kirigami.Units.smallSpacing
+            spacing: 0
+            visible: !root.showingProgress && root.osdList.length > 0
+
+            Repeater {
+                model: root.osdList
+
+                PlasmaExtras.Heading {
+                    required property string modelData
+                    required property int index
+
+                    Layout.fillWidth: true
+                    padding: Kirigami.Units.smallSpacing
+                    level: 3
+                    horizontalAlignment: Text.AlignHCenter
+                    verticalAlignment: Text.AlignVCenter
+                    textFormat: Text.PlainText
+                    wrapMode: Text.NoWrap
+                    elide: Text.ElideRight
+                    text: modelData
+                    opacity: index === root.osdListIndex ? 1 : 0.6
+
+                    PlasmaExtras.Highlight {
+                        anchors.fill: parent
+                        z: -1
+                        hovered: true
+                        visible: parent.index === root.osdListIndex
+                    }
+                }
+            }
         }

         RowLayout {
